namespace BlazorApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            new Notification { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new Notification { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new Notification { Id = _nextId++, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
        });

        // Background thread that generates a new notification every ~7 seconds.
        _ = Task.Run(async () =>
        {
            var messages = new[]
            {
                "Server backup completed.",
                "A new user signed up.",
                "Deployment succeeded.",
                "Disk usage above 80%.",
                "Scheduled maintenance tonight.",
                "New comment on your post.",
            };

            var rng = new Random();
            while (true)
            {
                await Task.Delay(TimeSpan.FromSeconds(7));
                lock (_lock)
                {
                    _notifications.Add(new Notification
                    {
                        Id = _nextId++,
                        Message = messages[rng.Next(messages.Length)],
                        Timestamp = DateTime.UtcNow,
                    });
                }
            }
        });
    }

    public List<Notification> GetNotifications()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    public List<Notification> GetNotificationsSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }
}

